    faq_a_glib_friends: "Et tema om venskab og varme med andre mennesker: få nye venner, lytte for alvor, genoptage et gammelt venskab, invitere venner hjem, et venligt ord hver dag, og et smil og et hej. To små idéer i det kommer fra Dale Carnegies klassiker \"Vind venner, indflydelse og fremgang\" – at huske navne og at være oprigtigt interesseret i andre. Tryk på \"+ Læsehjørne\" på bogkortet for at tilføje bogen til Læsehjørne, under \"Venter\" – og så forsvinder kortet fra målene.",
