    faq_a_nm_me_card: "Ja. I \"Min figur\" (tryk på Me i New Me) har hver Me, du allerede har nået, en lille delingsknap i hjørnet. Den laver et glasagtigt kort som et billede – din Me, der lyser på en nattehimmel, dens trin, dit fornavn, din dag på rejsen og dine nøgler – og åbner delingsmenuen, så du kan sende det på WhatsApp eller gemme billedet. Det er kun et billede, så venner kan se det, men ikke tage din Me.",
