    bag_ex_tb_gifts: "Gaveidéer",
    bag_examples_v2_toast: "🎁 Nye eksempler i din taske: gaveidéer, en pakkeliste til hotellet og en til flyveturen ✨",
    faq_a_bag_examples_list: "En ny taske kommer med eksempler, som du kan rette eller slette som alt andet: Hjem (indkøb, opskrifter, ugens måltider), Familie (små øjeblikke, en liste til fødselsdagsfesten, aktiviteter og hold), Idéer (idéer til weekenden, gaveidéer efter hvor tæt du er på personen, og hvad du vil gøre med sparede penge) og Ture (steder, du vil hen, pakkeliste til turen, pakkeliste til hotellet og en liste til at flyve til udlandet). En taske, der fandtes i forvejen, får de nyeste én gang, i sine egne lommer.",
    faq_q_bag_examples_list: "Hvilke eksempler er der i Min taske?",
    faq_a_nm_me1_guide: "Me – din figur i New Me, i sin første form (Me1). Første gang, lige efter at du er blevet medlem, åbner en portal af lys sig med gnister hele vejen rundt, og Me flyver ud af den, forklarer med et par tryk, hvad der venter, og bliver derefter ved hvert spørgsmål: mens måltiderne vælges, skriver den sammen med dig i sin bog, og et tryk på dens tip viser et nyt. Til sidst fejrer Me det med dig og tager dig med på en kort rundtur – og når rundturen er slut, har den endnu et lille øjeblik med dig. Hvis du går midt i det – spørgsmålene eller rundturen – bliver Me glad for at se dig næste gang og spørger, om I skal fortsætte fra samme sted. »Spring over« øverst springer åbningen over.",
    faq_q_nm_me1_guide: "Hvem viser vej ind i New Me?",
    nm_m1_day_text: "Hver dag – et ✓ ved hvert måltid, og jeg tæller det hele for dig.",
    nm_m1_go: "Så går vi i gang ✨",
    nm_m1_heart_btn: "Sammen 💛",
    nm_m1_heart_text: "Skridt for skridt. Jeg er her – altid.",
    nm_m1_heart_title: "Lad os gå denne vej sammen 💛",
    nm_m1_hi_text: "Fra i dag er jeg lige her hos dig – ved hvert skridt på vejen.",
    nm_m1_hi_title: "Hej! Jeg er Me ✨",
    nm_m1_joy_btn: "En hurtig rundtur ✨",
    nm_m1_joy_text: "Din menu venter, og den magiske verden er allerede ved at vågne.",
    nm_m1_joy_title: "Hurra! Det hele er klar 🎉",
    nm_m1_magic_text: "Og hvert ægte skridt fremad, du tager, åbner en magisk verden 🗝️",
    nm_m1_menu_text: "Sammen laver vi en menu helt efter dig: mad, du elsker, på tidspunkter, der passer dig.",
    nm_m1_portal: "En ny verden åbner sig ✨",
    nm_m1_q_about: "Hyggeligt at møde dig! ✨",
    nm_m1_q_agree: "Før vi begynder – et par vigtige ord 🤍",
    nm_m1_q_letter: "Et par ord til dit fremtidige jeg? Jeg passer godt på dem for dig 🔒",
    nm_m1_q_menu: "Lad os skrive drømmene sammen – og gøre dem til virkelighed sammen ✨",
    nm_m1_q_plan: "Du kan skifte når som helst – her er der intet forkert valg.",
    nm_m1_q_times: "Dine tider er også mine tider ⏰",
    nm_m1_ready_text: "Først et par små spørgsmål – så vælger vi måltiderne sammen.",
    nm_m1_skip: "Spring over",
    nm_m1_tip_ai: "En madret, der ikke er på listen? Senere kan du skrive den med dine egne ord under »Byt« – og AI regner den ud. Og nu vælger vi sammen, hvad du skal spise hver dag – og selvfølgelig kan du altid bytte ✨",
    nm_m1_tip_love: "Det er lige meget hvilken mad – elsker du den, bliver den på menuen 💛",
    nm_m1_tip_rice: "Ris er min favorit: det er basen, med lidt af det hele rundt om 🍚",
    faq_a_shop_basics: "Når Indkøbslisten er helt tom – for eksempel helt i starten – vises en basisliste at starte med: mælk, brød, æg og mere. Et tryk på en vare føjer den til listen, og »Tilføj alle« tilføjer det hele på én gang. Så snart der står noget på listen, forsvinder basislisten.",
    faq_q_shop_basics: "Hvad er basislisten i en tom Indkøbsliste?",
    shop_basics_all: "Tilføj alle",
    shop_basics_items: "mælk|brød|æg|tomater|agurk|ost|ris|pasta|olivenolie|æbler|bananer|toiletpapir",
    shop_basics_title: "En basisliste at starte med",
    shop_order_empty: "Listen er tom lige nu",
    shop_order_hours: "Hvornår på dagen?",
    shop_win_evening: "Aften",
    shop_win_from: "Fra",
    shop_win_morning: "Formiddag",
    shop_win_noon: "Eftermiddag",
    shop_win_other: "Andet…",
    shop_win_to: "Til",
    room_genie_again_no: "Ikke lige nu",
    room_genie_again_no_msg: "Så er det tid til at nå de mål, du allerede har sat dig. Når du kommer til det næste – venter der noget på dig ✨",
    room_genie_again_q: "Tilbage igen? ✨ Vil du gerne ændre noget mere i dit liv?",
    room_genie_again_yes: "Ja",
    room_genie_bye: "Vi ses",
    room_genie_rest: "Skovånden hviler nu – kom tilbage i morgen ✨",
    faq_a_shop_holidays: "Tryk på gaven i Indkøbslisten: højtiderne i dit land (det, der er valgt i Indstillinger) vises i rækkefølge med datoer – som regnes ud af sig selv hvert år. Tryk på en højtid for at få en færdig liste over det, folk plejer at købe til den; alt er valgt (undtagen det, der allerede står på din liste), fjern fluebenet ved det, du ikke har brug for, og tryk på »Føj til listen«. To uger før en højtid dukker et lille kort op øverst på listen; ✕ skjuler det til næste højtid.",
    faq_q_shop_holidays: "Hvordan virker »Hvad skal købes til højtiden«?",
    shop_hol_add: "Føj til listen ({n})",
    shop_hol_added: "Føjet til listen: {n}",
    shop_hol_btn: "Hvad skal købes til højtiden",
    shop_hol_items_title: "{holiday} – hvad skal købes?",
    shop_hol_not_now: "Ikke nu",
    faq_a_shop_delivery: "Tryk på lastbilen i Indkøbslisten: vælg, hvad der er i leveringen (alt er valgt), hvornår den kommer – i dag, i morgen eller en anden dag – og hvornår på dagen (formiddag, eftermiddag, aften eller »Andet…« til dine egne tider). De varer flyttes til kortet »På vej« øverst på listen, med dagen og tidsrummet. Når dagen kommer, dukker »Er leveringen kommet?« op i Min Dag (og kortet har »Er den kommet?«). Er alt kommet, flyttes de til »Køb igen«. Mangler noget, trykker du på det, der ikke kom, så ryger det direkte tilbage på listen.",
    faq_a_shop_departments: "Listen sorterer sig selv efter afdelingerne i supermarkedet – frugt og grønt, brød, mejeri og æg, kød og fisk, kolonial, frost, drikkevarer, snacks, rengøring, personlig pleje, baby og kæledyr – så du går gennem butikken i rækkefølge. Afdelingen genkendes ud fra varens navn. Er en vare havnet det forkerte sted, så tryk på den og vælg dens afdeling, eller »Andet…« for at skrive din egen.",
    faq_a_shop_share_qty: "Ja. Ved siden af hver vare lægger + én til (×2, ×3…), og − trækker én fra. Del-knappen øverst i Indkøbslisten sender hele listen, pænt sorteret efter afdeling, på WhatsApp, e-mail eller som en kopi.",
    faq_a_shop_two_buttons: "Begge betyder »købt«. ✕ er til noget, du køber én gang – det forsvinder fra listen (og venter i arkivet 🗑️, hvis det var en fejl). ↺ er til ting, du køber igen og igen – de forsvinder fra listen og venter i »Køb igen«: den lille ↺-knap ved siden af skraldespanden nederst på listen åbner det, og ét tryk dér sætter en vare tilbage på listen. Under »Rediger« derinde kan du tage en vare ud. Når du tilføjer en vare, dukker ting, du har købt før, op som forslag, og står den allerede på listen, bliver den bare til ×2 i stedet for en ny linje.",
    faq_q_shop_delivery: "Hvordan virker »Jeg har bestilt levering«?",
    faq_q_shop_departments: "Hvorfor er min indkøbsliste delt op i afdelinger?",
    faq_q_shop_share_qty: "Kan jeg angive en mængde eller sende listen til nogen?",
    faq_q_shop_two_buttons: "Hvad gør ↺ og ✕ ved siden af en vare på indkøbslisten?",
