    faq_a_new_me_challenge_journal: "Når en udfordring slutter – stor, mini eller ugens udfordring – har fejringen en knap 📝 Hvordan gik det?, som åbner en side i udfordringsdagbogen: hvordan det føltes (fem ansigter), hvad der hjalp, hvad der var svært, og hvad jeg tager med mig videre – intet af det er obligatorisk, og det kan også vente til senere. Dagbogen er en diamant i den magiske rygsæk: hver gennemført udfordring med dato og det, der blev skrevet, den nyeste først – tryk på en for at læse, redigere eller dele den (kun det, der står på siden, deles). En gennemført udfordring får også en medalje under præstationerne, i »Udfordringer, jeg har gennemført«. Udfordringsdagbogen er adskilt fra den almindelige dagbog.",
    faq_q_new_me_challenge_journal: "Hvad er udfordringsdagbogen?",
    nm_badges_challenges: "Udfordringer, jeg har gennemført",
    nm_chj_empty: "Udfordringer, du gennemfører, vises her",
    nm_chj_hard: "Hvad var svært?",
