    nm_chj_q: "Hvordan gik udfordringen?",
    nm_chj_reflect_btn: "Hvordan gik det?",
    nm_chj_save: "Gem i udfordringsdagbogen",
    nm_chj_saved: "Gemt i udfordringsdagbogen",
    nm_chj_share_text: "Jeg har gennemført en udfordring i New Me ✨",
    nm_chj_take: "Hvad tager jeg med mig videre?",
    nm_chj_title: "Udfordringsdagbog",
    nm_chj_write: "Skriv, hvordan det gik",
    nm_swap_time: "Tidspunkt",
    faq_a_ai_reminder_in_text: "Ja – skriv den sammen med opgaven, for eksempel »i morgen kl. 17:00 hente pakken, med en påmindelse en time før«. Påmindelsen gemmes på selve opgaven: en time før, en halv time, dagen før og så videre, og »mind mig om det« uden tidspunkt betyder 10 minutter før. En påmindelse skrevet i teksten har forrang for påmindelsesfeltet i samme vindue.",
    faq_q_ai_reminder_in_text: "Kan jeg bede AI-assistenten om en påmindelse i samme anmodning?",
    myday_meals_all_done: "Alle dagens måltider er krydset af 🍽️",
    nm_tour_week_text: "En lille udfordring for ugen. ✓ hver dag – en nøgle til sidst.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "af {total}",
    books_home_off_toast: "Bogen er fjernet fra startskærmen",
    books_home_on_toast: "Bogen ligger på startskærmen 📖",
    books_home_pin: "På startskærmen",
    books_home_q: "Hvilken side er jeg på?",
    books_home_save: "Gem",
    faq_a_books_home_chip: "Ja. I Læsehjørne, på kortet for en bog, du læser lige nu, trykker du på 📌 På startskærmen. En lille knap med bogen og siden vises under hilsenen på startskærmen – tryk på den, skriv det nye sidetal og gem, så registreres fremskridtet (også i Læsehjørne). Tryk på 📌 igen, så fjernes den. Flere bøger kan være der på én gang – en knap til hver – og det er det samme på alle enheder.",
    faq_a_new_me_week_challenge: "En lille udfordring for en uge, som du selv vælger. I gangen er der et stort kort: »Hvad vil du arbejde med i denne uge?« – tryk på det, vælg et område (med mig selv, med andre, lære og vokse, ro, små modige skridt, hjem og rutiner) og en udfordring, og vælg, hvornår den starter. De samme udfordringer findes også på udfordringsskærmen under 🌱 Personlig udvikling. Hver dag sætter du ✓ på kortet (én fridag om ugen), og hver uge, der slutter, giver en ny nøgle til den hemmelige verden. »Læse 2 sider om dagen« krydses af automatisk ud fra siderne, der logges i Læsehjørne. Når ugen er slut, føjer 📌 Behold som daglig opgave den til Min Rutine på det tidspunkt, du vælger, med et ✓ hver dag. Én ugeudfordring kører ad gangen; de store udfordringer og miniudfordringerne fortsætter ved siden af.",
    faq_a_room_genie: "På verandaen ved havet får et tryk på Aladdins lampe skovånden til at stige frem – og en samtale begynder: hvad er dit ønske (hvad vil du gerne ændre i dit liv), hvordan det føles, når det går i opfyldelse, hvad der er svært på vejen, og hvordan situationen lige nu kan vendes til noget godt. Så cirka hvor lang tid det tager, et første lille skridt og to til, og et »hvis… så…« til, når det bliver svært. Til sidst vises hele ønsket skridt for skridt, og det kan blive et mål i Mine Mål (skridtene bliver milepæle på stien, med dato efter den valgte tid; der kan alt ændres) eller gemmes i dagbogen – og så siger skovånden farvel. Intet gemmes, medmindre man vælger en af dem. Fra andet besøg spørger skovånden først, om du gerne vil ændre noget mere i dit liv: ja – den samme samtale; ikke lige nu – en påmindelse om at nå de mål, der allerede er sat. Skovånden kommer frem én gang om dagen: når et ønske er gemt (eller efter »Ikke lige nu«), hviler den til i morgen. Spørgsmålene følger en kendt måde at gøre et ønske til en plan: ønske, udfald, forhindring og plan.",
    faq_q_books_home_chip: "Kan jeg se min bog og side på startskærmen?",
    faq_q_new_me_week_challenge: "Hvad er ugens udfordring?",
    faq_q_room_genie: "Hvad gør lampens ånd?",
