    faq_a_new_me_game: "I New Me bliver spilknapperne altid på samme sted – i gangen, i det hemmelige værelse og overalt i skoven; kun maleriet i midten skifter. Øverst: dagen på rejsen, nøgler, dage i træk og dagens energi (hvor meget der er spist af planen), og under det den næste mission – det næste måltid med klokkeslæt (et tryk åbner det, med ✓ Jeg har spist). På siden: hele dagen, udfordringer og min rejse, og ved siden af dem ugens udfordring – dens 7 dage og et ✓ for i dag. Nederst: den magiske rygsæk (hele New Me – verdenskortet, min rejse, indkøbsliste, præstationer, udfordringsdagbog, kropsmål, billeder, månedskalender, dagstabel, påmindelser, menu-PDF og indstillinger; den åbner som sin egen skærm). Verdenskortet, det første i rygsækken, viser alle steder i skoven – tryk på et sted for at gå derhen; på et låst sted kan du se, hvor mange nøgler det kræver. Me er din figur på skovstien: den begynder som Me1, efter nogle udfordringer (4 nøgler) vokser den til Me2 og mod slutningen (9 nøgler) til Me3 – med en forvandling, du kan se ske. Tryk på Me for at se alle trinene – hver figur, du allerede har nået, kan vælges igen, så en tidligere kan komme tilbage. Me svæver – træk den med fingeren eller musen, og indgangen, den rører ved, åbner sig (en låst viser, hvor mange nøgler der mangler). Me følger også med ind i hvert rum og hvert sted og svæver, hvor du efterlader den: træk den hvorhen du vil, og træk den lysende ring under den for at dreje den hele vejen rundt; den kigger i den retning, den bevæger sig (på en computer: pilene flytter den, Q og E drejer den). I gangen går den lille 🏠 under den øverste bjælke tilbage til startskærmen; i hvert rum og på hvert sted går knappen i samme hjørne tilbage til gangen.",
    faq_q_new_me_game: "Hvordan fungerer spilknapperne, verdenskortet og Me?",
