    room_magic_song_rec3: "Vandfaldets klokkespil",
    faq_a_new_me_menu_build: "Først spørger spørgeskemaet, hvilke måltider du spiser og hvornår (2 måltider + et mellemmåltid, 2 måltider + en let aftensmad, eller begge), og om der er noget om aftenen – at spise eller drikke, hvad og hvornår. Med »2 måltider + et mellemmåltid« er måltiderne frokost (11:30) og aftensmad (19:00), med mellemmåltidet kl. 16:00. Derefter vises alle mulighederne for de måltider. Vælg op til 2 favoritter til hvert måltid – i menuen står der »det ene eller det andet«. I nogle muligheder (pita og smørepålæg, cornflakes og mælk, noget let) vælger du op til 3 ting, du kan lide, hver i sin egen portion, og i menuen står der »det ene eller det andet eller det tredje«; kalorierne følger det, du har valgt. Kaffe og drikke fungerer på samme måde. Hvert valg afbalanceres, så dagen giver præcis 1.300 eller 1.500. Vil du ændre det når som helst: ⚙️ Indstillinger → 🍽️ Sammensæt din menu, eller »Vælg op til 3, du kan lide« på måltidets kort.",
    faq_q_new_me_menu_build: "Hvordan bygges New Me-menuen op?",
