    faq_a_myday_water_toggle: "Ja. Vandglasset i 'Min Dag' (med + for et glas mere) vises som standard. For at skjule det skal du slå »Vis vand i 'Min Dag'« fra i Indstillinger > Personalisering og kalender. Intet slettes – vandsporingen fortsætter med at virke, og når kontakten slås til igen, kommer glasset tilbage.",
    faq_q_myday_water_toggle: "Kan jeg skjule vandet i 'Min Dag'?",
    myday_water_toggle_label: "Vis vand i 'Min Dag'",
    faq_a_routine_newme_sync: "Med New Me har ⚙️ i Min Rutine en kontakt 'Synkroniser med New Me'. Når den er slået til (standard), vises dagens New Me-måltider i Min Dag og i Min Rutine – i stedet for de rutinemåltider, der blev skjult. Når den er slået fra, forsvinder New Me-måltiderne fra begge, og rutinen er præcis som før. Intet slettes – slår du den til igen, kommer alt tilbage, og du bliver spurgt, hvilke rutinemåltider der skal skjules.",
    faq_q_routine_newme_sync: "Hvordan slår jeg synkroniseringen af New Me med Min Rutine og Min Dag til eller fra?",
