    theme_name_watercolor_wash: "Akvarel",
    faq_a_food_list_languages: "Den indbyggede madliste startede med israelske retter og deres hebraiske navne. På alle andre sprog vises hver fødevare med sit engelske navn, og søgningen finder alle engelske navne, den kender (for eksempel finder 'broth' Clear soup); fødevarer, der kun har et hebraisk navn, vises ikke. Det, der ikke er på listen, kan du bare skrive med dine egne ord – AI-estimatet virker på alle sprog.",
    faq_q_food_list_languages: "Hvorfor viser madlisten engelske navne, og færre fødevarer, på mit sprog?",
    settings_copyright_line: "© 2026 alle rettigheder forbeholdes. appen er udviklet af eden zabari.",
    workout_ready_replace_btn: "Erstat",
    faq_a_sport_workout_ai: "I Mine træninger → ⋯ → Plan med AI (og når tabellen er tom, også på feltet ved siden af de færdige planer). Svar med et par tryk – hvor mange gange om ugen, hvornår, sted, niveau og mål, næsten alle også med \"Andet\" – og tilføj gerne en fri linje, som et ømt knæ eller at løbe 5 km inden sommeren. AI'en laver en hel uge: typer træning, dage, tider, varighed, intensitet, øvelser og hviledage. Før noget gemmes, vises en forhåndsvisning: \"Sæt den i min tabel\" (i stedet for tabellen eller oven i den), \"Et andet forslag\" (op til 3 gange) eller \"Skift svar\". Planen er bevidst moderat, og nævner du smerter eller en skade, får du skånsomme muligheder og rådet om at tale med en fagperson. Den bruger samme AI-kvote som skemaet og rutinen: 5 gange gratis og 60 gange om måneden med Premium.",
    faq_q_sport_workout_ai: "Hvordan laver jeg en træningsplan med AI?",
    workout_ai_add: "Oven i min tabel",
    workout_ai_again: "Et andet forslag",
