    workout_ai_other: "Andet",
    workout_ai_replace: "I stedet for min tabel",
    workout_ai_title: "Træningsplan med AI",
    workout_ai_when_evening: "Aften",
    workout_ai_when_label: "Hvornår",
    workout_ai_when_morning: "Morgen",
    workout_ai_when_noon: "Middag",
    workout_ai_when_ph: "f.eks. efter arbejde, eller 17:30",
    workout_ai_working: "Planen laves…",
    faq_a_sport_workout_jar: "Hver type træning har sin egen farvede stjerne – løb lyserød, gang grøn, svømning blå og så videre. Hver træning, du registrerer i denne uge, fra planen eller for sig, taber sin stjerne ned i glasset øverst i Mine træninger, og glasset fyldes op mod dit ugemål (tryk på det for at ændre målet). Når du når målet, gløder glasset. Det lille glas ved siden af tæller, hvor mange uger i træk du har fyldt det.",
    faq_q_sport_workout_jar: "Hvad er de farvede stjerner og glasset i Mine træninger?",
    faq_a_sport_workout_gcal: "Ja – under ⋯ → Google Kalender (når Google Kalender er forbundet i Indstillinger). Hver træning med et tidspunkt bliver en begivenhed, der gentages hver uge på dens dage, og ændringer i appen opdaterer den. Påmindelser kommer kun fra appen, så Google tilføjer ikke sine egne, og træningerne vises aldrig dobbelt i appen. Et nyt tryk fjerner kun træningerne fra Google Kalender.",
    faq_q_sport_workout_gcal: "Kan mine træninger vises i Google Kalender?",
    workout_gcal_btn: "Google Kalender",
    workout_gcal_error: "Google Kalender kunne ikke opdateres – det prøves igen ved næste ændring",
    workout_gcal_not_connected: "Forbind Google Kalender i Indstillinger først",
    workout_gcal_off_toast: "Træningerne blev fjernet fra Google Kalender",
    workout_gcal_on_toast: "Dine træninger er i Google Kalender",
    faq_a_sport_workout_reminder: "Ja – i en træning, Påmindelse: 10 minutter, 30 minutter eller en time før, eller en egen tid (træningen skal have et tidspunkt). Den ringer som dine andre påmindelser, én gang og ét sted: i appen hvis den er åben, ellers på din telefon. \"Færdig\" registrerer træningen i historikken, og \"Ikke endnu\" minder dig igen om 5 minutter.",
    faq_q_sport_workout_reminder: "Kan jeg få en påmindelse før en træning?",
    workout_reminder_30min: "30 minutter før",
    workout_reminder_label: "Påmindelse",
    workout_reminder_need_time: "Tilføj et tidspunkt for at få en påmindelse",
    faq_a_sport_workout_share: "Under ⋯ → Del bliver ugen til et glasagtigt billede i dit temas farver, med et diskret link til appen (på telefonen går det direkte til delingsmenuen, på computeren gemmes billedet). ⋯ → PDF til udskrift åbner en ren side med hele ugen og et felt at sætte kryds i ved hver træning og øvelse – vælg \"Gem som PDF\" eller udskriv den. Planen står også i datarapporten i Indstillinger, under Sport.",
    faq_q_sport_workout_share: "Hvordan deler eller udskriver jeg min træningsuge?",
    share_image_saved: "Billedet er gemt – du kan vedhæfte det",
    share_save_image: "Gem billedet",
    workout_pdf_btn: "PDF til udskrift",
    workout_share_btn: "Del",
    faq_a_sport_workout_board: "Under ⋯ → Ugetavle er hver dag en kolonne: træk en træning til en anden dag (på telefonen, hold først inde). I en træning sætter \"Også i Min Rutine\" den ind i din rutine på dens tid og dage, og ændringer holdes i sync begge veje; fra et punkt i Min Rutine gør \"Tilføj til mine træninger\" det modsatte. Et ✓ ét sted tæller begge steder, og i Min Dag vises den kun én gang – i brikken ved siden af vandet.",
    faq_q_sport_workout_board: "Hvordan flytter jeg en træning til en anden dag og forbinder den med Min Rutine?",
    routine_in_workouts_btn: "Åbn i mine træninger",
    routine_to_workout_btn: "Tilføj til mine træninger",
    routine_to_workout_done: "Tilføjet til mine træninger 💪",
    workout_delete_confirm_routine: "Den fjernes fra planen og fra Min Rutine. Træninger, der allerede er registreret i historikken, bliver.",
    workout_moved: "Flyttet til {day}",
    workout_routine_need_time: "Tilføj et tidspunkt for at sætte den i Min Rutine",
    workout_routine_toggle: "Også i Min Rutine",
    workout_view_board: "Ugetavle",
    workout_view_timeline: "Tidslinje",
    faq_a_sport_workout_plan: "I Træningssporing, under \"Mine træninger\": + Træning – type, dage, tid, varighed, intensitet og sted (også \"Andet\"). Styrke-, funktionelle og svømmetræninger kan have en liste med øvelser, og Hvile markerer en hviledag. Du kan også starte fra en færdig plan. Dagens træning vises stort, med hele ugen nedenunder; ✓ registrerer den i træningshistorikken sammen med intensiteten. Under ⋯ sætter du et ugemål (træninger eller minutter) – hver træning, du laver, taber sin stjerne ned i glasset.",
    faq_a_sport_workout_today: "I Min Dag, ved siden af vandet, viser en lille brik dagens træning – et tryk åbner detaljer, ✓ og ▶. ▶ starter en timer, der fortsætter i brikken på startskærmen, og \"Afslut\" registrerer træningen med den rigtige tid. Hvis udfordringen \"To uger i bevægelse\" i New Me er i gang, tæller en registreret træning med der af sig selv.",
    faq_q_sport_workout_plan: "Hvordan planlægger jeg min træningsuge?",
    faq_q_sport_workout_today: "Hvor ser jeg dagens træning, og hvordan virker timeren?",
