    faq_a_new_me_magic_themes: "Fem glitrende temaer, der følger med New Me: Fortryllet skov, Stjernestøv, Rosefe, Magisk nordlys og Gylden skumring. Vælg et i New Me (⚙️ Indstillinger > Farver) eller under Indstillinger > Udseende og skærm, så maler en glimmerpensel skærmen i det tema. Et magisk tema giver glimmer i hele appen og ved hvert tryk. Du kan altid skifte tilbage til et hvilket som helst andet tema.",
