    apptour_focus_text: "Alt træder til side undtagen den ene ting lige nu – med et stort ✓. Så dukker den næste op.",
    apptour_m_presets_text: "Dine gemte måltider ét sted: søgning, senest brugt, efter tid på dagen – og ＋ tilføjer et til i dag.",
    apptour_night_text: "🌙 gør hele appen mørk, ☀️ henter dagen tilbage.",
    apptour_noteline_text: "Skriv og tryk på ➤ – det gemmes i dine noter. 📝 i starten skifter til 🛒 indkøb eller 🍎 et gemt måltid.",
    apptour_search_text: "Noter, indkøb, kalender, opskrifter, notesbøger, mål, tabeller og bøger – én søgning finder det hele.",
    faq_a_new_me_ai_menu: "Før menuen spørger spørgeskemaet, hvilke måltider du spiser og hvornår (2 måltider + et mellemmåltid, 2 måltider + en let aftensmad, eller begge), om du spiser noget lille om aftenen og hvornår, hvad du ikke spiser, og hvordan du drikker kaffe eller te. Derefter laver AI 3 forslag til hvert måltid – hvert så stort som måltidets andel af dagen, så dagen stadig giver præcis 1.300 eller 1.500 – plus drikkeidéer, der gemmes som dine faste drikke. Vælg op til 2 favoritter pr. måltid; forslagene fra den oprindelige menu ligger lige under, og under 🔄 Byt kommer de efter din personlige menu. 🔄 Andre forslag laver et nyt sæt (3 gange pr. spørgeskema). Vil du ændre svarene eller lave en ny menu når som helst: ⚙️ Indstillinger → ✨ Personlig menu (AI).",
