    nm_sales_premium: "Hele Premium er inkluderet",
    nm_unlock_premium: "Og hele Premium er også låst op.",
    settings_sub_status_newme: "Premium er inkluderet i din New Me.",
    room_back_to_shelf: "Til hylden",
    faq_a_new_me_day_total: "Hver dag ender præcis på planen: måltiderne, omkring 150 kalorier til kaffe og drikke i løbet af dagen, og det, der er valgt til aftenen – noget lille at spise eller noget at drikke. Til aftenen vælger du op til 3, du kan lide (for eksempel en banan, en yoghurt eller 2 stykker mørk chokolade; eller urtete, te med lidt mælk eller varm mælk), og deres kalorier trækkes fra måltiderne. Hvert valg balancerer sig selv: et mindre eller større alternativ, et måltid, der er taget fra, den lille morgenmad og det lille måltid, der følger med den, eller aftenen – forskellen lægges til måltiderne eller trækkes fra dem, hvert efter sin størrelse, og under hvert måltid står der, hvor meget (+ eller −) og hvad der kan lægges til eller tages fra. Et måltid, der allerede er krydset af, bliver, som det blev registreret. I spørgeskemaet viser hvert måltid sin justering, og en lille boks viser måltider, drikke, aftenen og totalen. Lyst til noget andet den dag? Hold totalen på lige så mange kalorier eller færre.",
    faq_q_new_me_day_total: "Hvordan ender en New Me-dag på præcis 1.300 / 1.500, og hvor tæller drikke med?",
