    nm_swap_balanced: "{n} kalorier fordelt på måltiderne, så dagen ender på {plan}",
    books_quotes_chip: "Citater",
    faq_a_book_quotes: "På hylden i det hemmelige værelse (Citater), eller med det lille mærke 💬 Citater i Læsehjørnet – det er den samme liste. Tryk på \"+ Citat\", skriv sætningen og vælg bogen fra Læsehjørnet, eller skriv en anden titel med \"✏️ Andet\"; forfatteren er valgfri. ✏️ retter et citat, og 🗑️ sletter det. Citaterne er bogmærker, du swiper imellem – 🎨 øverst skifter til billeder eller en væg af kort.",
    faq_a_room_wish_jar: "På hylden i det hemmelige værelse står et glas til drømme. Tryk på det lille glas på øverste hylde (eller Hylden > Ønskeglasset) og skriv, hvordan du gerne vil have, at dit liv skal se ud – så vildt du vil, uden rigtigt eller forkert. Hvert ønske foldes til en seddel, der falder ned i glasset. »Træk en seddel« åbner en tilfældig, og hver seddel kan også åbnes for sig. Fra anden gang, du åbner det samme ønske, kan du gøre det til et mål og dele det op i små skridt. En gang om ugen dukker en seddel med et af dine ønsker blidt op – uden pres, bare en påmindelse om, hvor du er på vej hen.",
    faq_q_book_quotes: "Hvor gemmer jeg citater fra bøger, jeg har elsket?",
    faq_q_room_wish_jar: "Hvad er ønskeglasset i det hemmelige værelse?",
