    room_wish_written: "Skrevet {date}",
    faq_a_saved_meals_page: "Gemte måltider har deres egen side: Ernæring og Målinger > ⭐ Gemte måltider (eller ⭐ i menuen). Søgningen øverst finder et måltid på navn eller ingrediens, \"Brugt for nylig\" viser, hvad du har tilføjet på det seneste, og fanerne (Morgenmad, Frokost, Aftensmad, Supper…) viser hver tid på dagen. \"+ I dag\" tilføjer et måltid til dagens Daglige Måltidssporing, på næste ledige plads. Tryk på et måltid for at rette eller slette det, og ＋ øverst tilføjer et nyt.",
