    presets_tab_soup: "Supper",
    presets_tab_sweet: "Slik",
    faq_a_notes_sticky_look: "Noter er en kort liste med glaskort – 🎨 øverst i Noter skifter udseende på hele Noter: listen, dagknapperne øverst og vinduet, hvor en note skrives – glas, ren liste, kartotekskort eller washitape. En note, der trækkes, beholder præcis sit eget udseende og sin egen farve. Tryk på teksten i en note for at åbne den – der kan du ændre den, skifte farver og se, hvornår den sidst blev skrevet. Tryk på ○, når den er klaret, og × flytter den til arkivet (🗑️ nederst i listen henter den tilbage). Træk den i ⠿ for at ændre rækkefølgen, ned under »Senere« eller op på en dag øverst. ! markerer en note som hastende – den glider blidt op til de første rækker med et lille »Haster«-mærke; et tryk mere fjerner markeringen.",
    faq_q_notes_sticky_look: "Hvordan åbner, ændrer eller fjerner jeg en note?",
    note_to_archive_btn: "Flyt til arkivet",
    faq_a_routine_clash: "Står der allerede noget på det tidspunkt de samme dage, får du to valg: \"Erstat\" – det nye får det tidspunkt, og du vælger et andet tidspunkt til det, der stod der (når du redigerer noget eksisterende, foreslås dets tidligere tidspunkt, så de to bare bytter plads), eller \"Begge\" – begge bliver stående på samme tidspunkt, det ene under det andet. Er dagene forskellige (for eksempel det ene søn–tor og det andet fredag), spørges der slet ikke.",
    faq_q_routine_clash: "Hvad sker der, hvis jeg lægger noget i rutinen på et tidspunkt, der allerede er taget?",
    routine_clash_both: "✌️ Begge – begge klokken {time}",
    routine_clash_move_btn: "Flyt og gem",
