    routine_clash_replace: "🔄 Erstat – og flyt \"{title}\" til et andet tidspunkt",
    routine_clash_title: "Klokken {time} står der allerede: {title}",
    faq_a_new_me_coffee: "Under dagens menu står en kort opsummering: hvor mange kalorier alle dagens måltider giver tilsammen, hvor meget der er tilbage til kaffe og drikke, og knapper til den kaffe og de drikke, der er valgt – ét tryk tilføjer det under Drikke. I »Vælg op til 3, du kan lide« under knapperne (og i spørgeskemaet) vælger du, hvad der vises: vand / danskvand, urtete, en light-sodavand, sort / americano (~5), te med lidt mælk (~25), vandbaseret kaffe med op til 100 ml mælk eller plantedrik (~50), let kakao, varm mælk eller almindelig kaffe / latte (~120).",
    faq_q_new_me_coffee: "Hvor tilføjer jeg kaffe, og hvordan ved jeg, hvor meget der er tilbage af dagen?",
