    nm_late_room_line: "Noget lille før sengetid · ~{n} kcal tilbage i dag",
    faq_a_recipe_examples: "Under dine egne opskrifter er der eksempelopskrifter: morgenmad, salater, supper, hovedretter, tilbehør, snacks, desserter og veganske retter, hver med tilberedningstid, kalorier pr. portion og hvor mange gram én portion vejer. Tryk på en opskrift for at åbne den, og \"Gem i Mine Opskrifter\" laver din egen kopi, som du kan redigere. Kategorimærkerne filtrerer, og et tryk mere på samme mærke viser alt igen.",
    faq_a_recipe_grams: "I en opskrift står der ved siden af kalorierne \"1 portion ≈ X g\". I dine egne opskrifter udfylder du \"Gram pr. portion\" (og tilberedningstiden, hvis du vil) i opskriftsformularen: begge er valgfrie, og tiden vises på opskriftens farvebånd.",
