    recipes_examples_title: "Eksempelopskrifter",
    faq_a_recipe_scan_multi: "Ja. I \"Tilføj Opskrift\" trykker du på 📷 og vælger ét billede eller flere (op til 6; en pdf virker også). Hvert billede vises i en kort liste, hvor du vælger, hvad det viser: Alt, Ingredienser eller Fremgangsmåde, og \"➕ Et billede mere\" tilføjer flere. Tryk så på \"✨ Scan opskriften\": AI'en samler det hele til én opskrift, i rækkefølge og uden dobbelte linjer, og det tæller som én scanning. Flere billeder, du vælger under 📷 Foto i AI-assistenten, åbnes også her.",
    faq_q_recipe_scan_multi: "Kan jeg scanne én opskrift fra flere billeder, for eksempel ingredienserne og fremgangsmåden hver for sig, eller to sider?",
    recipe_scan_add_more: "➕ Et billede mere",
