    faq_a_note_written_at: "Tryk på notens tekst for at åbne den. Indeni, under teksten, står der, hvornår den sidst blev skrevet, med præcis dato og klokkeslæt. Kun en ændring af selve teksten opdaterer det: arkivering og gendannelse, afkrydsning ✓, farver eller flytning af noten ændrer det ikke.",
    faq_q_note_written_at: "Hvordan ser jeg, hvornår jeg skrev en note?",
    note_written_at: "Sidst skrevet: {date}",
    faq_a_new_me_month: "I den magiske rygsæk → Månedskalender: hver dag er farvet efter, hvor mange måltider der blev krydset af, pilene ‹ › skifter måned, og under kalenderen står månedens gennemsnit af kalorier per dag. Et tryk på en dag viser, hvor mange måltider der blev krydset af, og hvor mange kalorier der blev spist den dag.",
    faq_q_new_me_month: "Hvor kan jeg se måneden bagud og mit gennemsnit af kalorier i New Me?",
    nm_month_avg: "Månedens gennemsnit: {kcal} kalorier om dagen · dage med registrering: {n}",
    nm_month_day_empty: "Der blev ikke noteret noget denne dag.",
    nm_month_day_line: "Afkrydsede måltider: {checks} · kalorier: {kcal}",
    nm_extra_line_small: "{n} kalorier til dette måltid, fra den lille morgenmad – f.eks. {ideas}",
    faq_a_new_me_small_breakfast: "En let morgenmad (ca. 170 kcal): en speltpita (op til 100 kcal) med smørepålæg eller ost samt en grøntsag – vælg op til 3, du kan lide, for eksempel 1 tsk chokoladepålæg, 1 tsk peanutbutter eller en skive skæreost (op til 22 %). Fordi den er lille, følger »Plus et lille måltid« med på et andet tidspunkt (halvanden time senere, for eksempel 11:30 → 13:00 – ethvert andet tidspunkt kan vælges): en pita mere med pålæg, proteinyoghurt og frugt, riskager og hytteost, cerealier og mælk eller halv pita og æg – op til ca. 200 kcal, med sit eget ✓. Det, der stadig er tilbage, fordeles på de andre måltider, og hvert måltid viser, hvor meget det fik, så dagens sum bliver som i planen. Vælg den i spørgeskemaet, eller skift til den kun for i dag med 🔄 – for eksempel når morgenmaden bliver sen.",
