    faq_a_ai_icon: "Ja – under Indstillinger > Udseende og skærm. Den bløde boble er standard, og med Premium kan du også vælge en svævende hjerne eller en robot.",
    faq_a_new_me_favorites: "Ja. I spørgeskemaet (og når du tager det igen fra indstillingerne) kan du vælge op til 2 muligheder til hvert måltid. Den første står i menuen, med en »eller«-linje under til den anden – et tryk på den skifter til den kun for i dag. Og hvis morgenmaden ikke blev spist til tiden, flytter »⏰ Senere« den til senere på dagen, uden at kalorierne ændres.",
    faq_a_theme_mode: "Nogle specialtemaer er pænest i mørkt – Akvarel, Nordlys, Barbie og de to glittertemaer –, så vælger du et af dem, skifter appen til mørk tilstand, og ethvert andet tema (også raketten) skifter til lys. Sort og Mørkegrå forbliver mørke. Du kan altid ændre det bagefter med 🌙 i menuen eller med Lys Tilstand i indstillingerne.",
    faq_a_water_month: "I vandsporingen. Hver registrering i dagens log viser tidspunktet, den blev tilføjet, og \"Månedstabel\" åbner hele måneden: hver dag viser, hvor mange liter der blev drukket (✓ når dagsmålet blev nået), og et tryk på en dag viser dens registreringer med klokkeslæt.",
