    dev_sim_panel_title: "PM – kun for dig",
    faq_a_new_me_weight_optional: "Nej. Både den nuværende vægt og målvægten i spørgeskemaet er valgfri. Hvis en vejning tilføjes senere (⚖️ Vægt under »Min rejse« i New Me eller i vægtloggen), regnes fremskridtet fra den første.",
    faq_q_new_me_weight_optional: "Skal jeg skrive min vægt i New Me?",
    nm_unlock_desc: "Menuen, udfordringerne og rejsen er klar – skridt for skridt, sammen.",
    nm_unlock_title: "New Me er låst op!",
    room_reveal_star: "En ny stjerne tændtes i teleskopet på taget ✨",
    faq_a_room_records: "Pladespilleren står i rummet fra starten, på træstubben ved lænestolen. Pladerne åbner de officielle videoer til store hits fra de seneste år på YouTube, og under dem er der fem rolige melodier, der spiller her i rummet – pladen drejer, mens de spiller, og »⏹ Stop« slukker musikken.",
    faq_a_room_roof_gifts: "De kommer med den 8. nøgle. Et tryk på teleskopet lader dig kigge gennem det: nattehimlen helt tæt på – træk (eller brug pilene) for at se dig omkring – og dine gennemførte udfordringer danner et stjernebillede i det, én stjerne for hver udfordring; et tryk på en stjerne viser, hvilken det var. Et tryk på den lille kiste åbner den – lige nu er den tom – og et tryk til lukker den.",
    faq_q_room_records: "Hvad er der på pladespilleren i det hemmelige værelse?",
    faq_q_room_roof_gifts: "Hvad er teleskopet og kisten på taget?",
    room_chest_letter: "Et lille brev til dig",
    room_chest_letter_1: "Hvert lille skridt på vejen var ægte – og hvert eneste tæller.",
    room_chest_letter_2: "At være venlig over for sig selv er en del af vejen, ikke en pause fra den.",
    room_chest_letter_3: "Nogle dage er lettere og andre tungere. At være der i dem begge er den ægte styrke.",
    room_chest_letter_4: "Det er tilladt at hvile. Hvile er også et skridt fremad.",
    room_chest_letter_5: "De forandringer, der holder, er de stille – de bygges dag for dag.",
    room_chest_letter_6: "I dag er en god dag at føle sig stolt – om så bare en lille smule.",
    room_chest_letter_7: "Det hele behøver ikke at blive gjort. Bare den næste lille ting.",
    room_chest_letter_8: "Uanset hvad der skete i går, er i dag en ny begyndelse.",
