    dev_sim_locked_toast: "🔒 Låst – sådan ser det ud før købet",
    faq_a_new_me_preview: "Ja. New Me-siden begynder med en kort video af det, der sker indeni: spørgeskemaet, lamperne i gangen, rygsækken, udfordringerne og nøglerne. Nedenunder står alt, hvad der er inkluderet, et kig på én dag og korte svar.",
