    ai_chat_food_edit: "✏️ Ret kalorier / protein",
    ai_chat_food_invalid: "Kalorier skal være et tal over 0",
    ai_chat_food_updated: "Opdateret:",
    faq_a_ai_chat_food_fix: "Ja. Under svaret i chatten trykker du på ✏️ Ret kalorier / protein, ændrer tallene og trykker på Gem. Kun det, der lige blev tilføjet, ændres – også hvis det blev lagt sammen med et mellemmåltid, der allerede var der. AI kan tage fejl, så det er værd at tjekke hurtigt.",
    faq_a_new_me_home_btn: "Med New Me åbner en lille 💎 ved siden af fokustilstand, øverst på startskærmen, dagens menu. Dagens måltider vises også i Min Dag, hvert med et ✓.",
    faq_a_routine_item_days: "Ja. Tryk på punktet i Min Rutine og vælg dets dage under 📅 Dage – for eksempel kun mandag til fredag. De andre dage vises det ikke i Min Dag og har intet ✓; i Min Rutine bliver det stående, svagere, med dets dage ved siden af. Kortet, der spørger til et punkt efter 3 dage uden ✓, tæller kun punktets egne dage.",
    faq_q_ai_chat_food_fix: "Kan jeg rette kalorier eller protein, efter at assistenten har registreret mad?",
    faq_q_new_me_home_btn: "Hvor er New Me på startskærmen?",
    faq_q_routine_item_days: "Kan et enkelt punkt i Min Rutine kun gælde bestemte dage?",
    routine_item_days_label: "📅 Dage",
    home_note_meal_ph: "Find et gemt måltid…",
    menu_quick_search: "Hurtig søgning",
    nm_times_hint: "Tip: du kan sætte det seneste tidspunkt, hvor du plejer at spise hvert måltid – fx 9:00, hvis du ofte spiser omkring kl. 8.",
    room_game_marquee: "På vejen – stop op og nyd det",
    room_sand_erase_aria: "Gnid for at viske det skrevne ud",
    faq_a_home_note_line: "Skriv på linjen midt på startskærmen, og tryk på ➤ (eller Enter) – den gemmes i Noter. Tryk på 📝 i starten af linjen, så bliver den til 🛒: så havner det, du skriver, på Indkøbslisten. Tryk én gang til for 🍎: skriv et par bogstaver, dine gemte måltider, der passer, dukker op, og ét tryk fører et af dem ind i dagens måltider. Med 🎤 kan du bare sige det.",
    faq_a_night_mode: "Åbn menuen ☰, og tryk på 🌙 øverst – hele appen bliver mørk. ☀️ samme sted henter dagen tilbage. Det findes også i Indstillinger, under Lys Tilstand.",
    faq_q_home_note_line: "Hvordan skriver jeg en hurtig note fra startskærmen?",
    faq_q_night_mode: "Hvordan skifter jeg til nattilstand?",
    menu_day_mode: "Dagtilstand",
    menu_night_mode: "Nattilstand",
    faq_a_secret_room_yoga: "For enden af skovstien står en lysende port, og bag den, ved et vandfald, sidder skovens væsner – Lumi, Puffi, Nixie og Sparklet – på deres måtter i en halvcirkel, og Flora, yogalæreren, sidder med ansigtet mod dem på den eneste måtte på stenen. Tryk på Flora: hun åbner øjnene, alt kommer tættere på, og samtalen begynder roligt, med tid til at læse – Flora spørger, hvordan alle har det, hvert væsen svarer under sit eget navn (med et lille billede af den, der taler, ved siden af hver linje), og så spørger hun dig, hvordan du har det med de mennesker, der står dig nær. Samtalen fortsætter efter dine svar – gode mennesker, en, det er svært med, eller at føle sig lidt alene. Hver vej slutter med en lille mission (den kan lægges direkte i Min Dag; når missionen er at skrive noget, er der et sted at skrive det, og det gemmes i den magiske dagbog) og en stilling med tre vejrtrækninger sammen. ↩ går et skridt tilbage, og ✦ starter en ny samtale. Den næste nøgle åbner vandfaldet: når du sætter dig på stenen, forsvinder alt, og kun lyden af vandet bliver tilbage. Når du læner dig over dammen, stiger et spørgsmål op af vandet – hvad ville dit sande jeg gøre i dag? – og svaret bliver en lille opgave i Min Dag. Det er et venligt øjeblik, ikke en erstatning for at tale med en fagperson.",
    faq_q_secret_room_yoga: "Hvad sker der til yoga i skoven?",
    room_back_to_forest: "Tilbage til stien",
    room_back_to_yoga: "Tilbage til yoga",
    room_item_waterfall: "Vandfaldet",
    room_waterfall_pool_aria: "Rør ved vandet",
    room_waterfall_rock_aria: "Sæt dig på klippen",
    room_yoga_guide_aria: "Tal med Flora",
    yg_g_alone: "Tak, fordi du deler. Det sker for alle en gang imellem.",
    yg_g_alone_q: "Hvad ville føles rigtigt, om så bare lidt?",
    yg_g_critic: "Kritik kan stikke længe. Den handler om ét øjeblik – ikke om hele mennesket.",
    yg_g_end: "Tak, fordi du kom til cirklen. Du kan komme tilbage, når du vil.",
    yg_g_gate: "Det er tilladt at sætte en grænse. En grænse er ikke en mur – den er en låge.",
    yg_g_good: "Hvor dejligt 💛 Hvem gjorde dig godt i denne uge?",
    yg_g_good_msg: "Gode mennesker fortjener at høre det. Et lille tak kan gøre hele deres dag.",
    yg_g_hard: "Tak, fordi du siger det. Hvad tynger mest?",
    yg_g_listen: "Ikke at blive hørt er udmattende. Din stemme betyder noget, også når den er stille.",
    yg_g_new: "Nye mennesker begynder med et lille hej. Et hold, en gåtur, en gruppe – ét skridt.",
    yg_g_old: "En, der allerede kender dig, er et varmt sted. En kort besked er nok.",
    yg_g_start: "Og nu til dig 🌿 Hvordan har du det med de mennesker, der står dig nær, for tiden?",
    yg_g_used: "Når vi giver og intet får tilbage, bliver noget indeni træt. Det er okay at lægge mærke til det.",
