    yg_pose_heart: "Nu et åbent hjerte 💗 Skuldrene tilbage, brystet bredt. Tre vejrtrækninger sammen.",
    yg_pose_tree: "Nu træet 🌳 Stå stabilt, den ene fod mod det andet ben, hænderne op. Tre vejrtrækninger sammen.",
