    nm_time_hour: "Time",
    nm_time_minutes: "Minutter",
    routine_time_taken: "Der står allerede noget på dette tidspunkt: {title}",
    faq_a_new_me_times: "I spørgeskemaet i starten, og når som helst i indstillingerne for New Me → »Måltidstider«. Hvis din rutine allerede har måltidstider, hentes de derfra – og rutinens måltider kan skjules, med New Me-måltiderne i stedet. Hvis ikke, vælger du, hvor mange måltider om dagen (2 måltider + et mellemmåltid / 2 måltider + en let aftensmad / 2 måltider + et mellemmåltid + en let aftensmad), og hvornår hvert måltid er. Med »2 måltider + et mellemmåltid« er det frokost kl. 11:30, mellemmåltid kl. 16:00 og aftensmad kl. 19:00 (alle kan ændres). Det er dine måltidstider overalt: i gangen, i Min Dag, i Min Rutine og i påmindelserne. Uanset hvad du vælger, bliver dagens kalorier de samme – det, der tages fra, fordeles på de andre måltider.",
    faq_q_new_me_times: "Hvordan indstiller jeg mine måltidstider i New Me?",
    nm_times_count: "Hvor mange måltider om dagen?",
    nm_times_from_routine: "Ja, hent dem fra min rutine",
    nm_times_hide: "Skjul måltiderne i min rutine, og vis New Me-måltiderne i stedet",
    nm_times_later: "Senere",
    nm_times_manual: "Nej, vælg her",
    nm_times_none_found: "Din rutine har ingen måltider endnu – vælg her hvor mange og hvornår.",
    nm_times_q: "Har din rutine faste tider til at spise?",
    nm_times_saved: "Måltidstiderne er gemt",
    nm_times_title: "Måltidstider",
    faq_a_routine_exact_time: "Ja. Når du beskriver en rutine for AI'en med et præcist klokkeslæt (som \"16:10 trading\"), gemmes det præcis sådan – uden at blive rundet af til hel time. Alt, der står i din rutine, vises altid på tavlen, også selvom timen ikke er valgt i timeindstillingerne, og når du fjerner en time, hvor der står noget, bliver du spurgt først. Du kan også ændre et tidspunkt manuelt: tryk på tidspunktet i elementets vindue, og vælg time og minutter.",
    faq_q_routine_exact_time: "Kan min rutine have et præcist klokkeslæt, som 16:10?",
