    faq_a_secret_room_diary: "Kun dig. Dagbogssiderne gemmes på din konto, så de er der på alle enheder, og ingen andre kan se dem. Den magiske dagbog på skrivebordet i det hemmelige værelse åbner den, og det gør dagbogen i musikhjørnet også. Under den nye side er der en foldet månedstabel: en prik markerer hver dag med en side, og et tryk på en dag åbner dagens sider – der kan du også slette en side. Når dagbogen først er åben, kan den også føjes til hovedmenuen – med kontakten i selve dagbogen eller i New Mes indstillinger.",
    faq_a_secret_room_places: "Hver indgang ved skovporten åbnes med sin egen nøgle. Bag dem: verandaen ved havet (på det lille bord Aladdins lampe – et tryk, og en skovånd stiger op af den i en magisk tåge, hvirvler rundt og starter en samtale om dit ønske – se »Hvad gør lampens ånd?«), guitaren og dagbogen (guitaren spiller en kort, rolig melodi og stopper af sig selv, og hver af de tre plader, der hænger i træet, spiller sin egen magiske melodi – tryk igen for at stoppe – og i dagbogen på stubben skriver du), åndedrætsrummet (en stille sø i solnedgang – en lotuslygte flyder på vandet: tryk på den, skriv et ønske, og den driver af sted med det, langt tilbage ud i søen; med tryllestaven kan du skrive i sandet, hvad du vil give slip på, og det bliver liggende, til du visker det væk med fingeren) og skovstien (den åbner om natten, og et tryk på lygterne skifter til dag; fra den store gren hænger en magisk gynge, på bænken kan man sidde, og et tryk på skiltet bringer det tæt på – en tavle med seks små spørgsmål at krydse af). På en låst indgang kan du se, hvor mange nøgler der mangler. For enden af stien fører en lysende port til yogaen ved vandfaldet – og derfra til selve vandfaldet.",
    faq_q_secret_room_diary: "Hvem ser dagbogen?",
    faq_q_secret_room_places: "Hvad er der bag dørene i gangen?",
