    ai_chat_ask_food: "Hvad spiste du? Skriv frit – f.eks. »2 skiver brød med ost«",
    ai_chat_ask_schedule: "Hvad skal i kalenderen? Skriv frit – f.eks. »eksamen søndag kl. 9«",
