    ai_chat_working_table: "Et øjeblik, laver tabellen…",
    dev_weather_preview_label: "Forhåndsvisning – kun på din konto:",
    faq_a_ai_chat: "Tryk på boblen, så åbner en chat. Vælg, hvad du vil gøre – noget til kalenderen, hvad du har spist, et billede af en opskrift eller en ny tabel – eller skriv bare, så forstår assistenten det selv. Til kalenderen kan du vælge én gang, hver uge eller hver dag. Svaret kommer i chatten, og derfra kan du gå videre til noget andet eller åbne kalenderen / hvad du har spist.",
    faq_a_new_me_hall: "New Me begynder ved porten til en magisk skov, og hver indgang i den er et sted: den runde dør i kæmpetræet fører ind i det hemmelige værelse, den hule træstamme til verandaen ved havet, svampehuset til guitaren og dagbogen, den lille pilebue til åndedrætsrummet, den store pilebue til skovstien, og blomsterbuen med stigen fører op til stjernetaget, når det er åbnet. På en låst indgang sidder der en lås. Din figur, Me, svæver på stien, og spilknapperne er hele vejen rundt: den næste mission, ugens udfordring, den magiske rygsæk med hele New Me, verdenskortet og værktøjerne. Et tryk på nøglerne øverst forklarer, hvordan man får nøgler.",
    faq_a_new_me_routine_meals: "Når der er sat måltider op i New Me, og Min Rutine også har måltider, spørger New Me, om de skal skjules, og New Me-måltiderne vises i stedet – så intet vises to gange. Min Rutine viser så New Me-måltiderne på deres tidspunkter, med 💎 og et ✓ (et tryk på et måltids navn åbner et vindue, hvor man kan vælge et andet måltid eller ændre dets tidspunkt, lige der over rutinen). Intet slettes: de kommer tilbage via ⚙️ Indstillinger i New Me → Måltider i rutinen, eller ved at slå »Synkroniser med New Me« fra under ⚙️ i Min Rutine. Uden et aktivt New Me kommer de tilbage af sig selv.",
    faq_a_room_computer: "Det er en lille chat, der begynder med »Hvordan går din dag indtil videre?« – godt, travlt eller hårdt – og fortsætter med dig trin for trin, helt frem til en lille mission til sidst (som også kan gå direkte ind i Min Dag). Svarene kan trykkes eller skrives frit – det, der skrives, kobles til det nærmeste svar. »↩ Tilbage« går et trin tilbage, så du kan svare anderledes, og »Ny chat« starter forfra når som helst. Efter en travl eller hård dag kan du vende tilbage til computeren senere samme dag: »Jeg er tilbage...« fortsætter samtalen. Det grønne lys nederst slukker og tænder computeren. Kun valgene gemmes, kun på denne enhed og kun til dagen er omme.",
    faq_q_ai_chat: "Hvordan taler jeg med assistenten?",
