    dictation_btn_aria: "Tal, så bliver det skrevet",
    dictation_mic_denied: "Mikrofonen er blokeret – tillad den via 🔒 ved siden af adressen i browseren, eller i telefonens indstillinger",
    faq_a_dictation: "Ja – tryk på mikrofonen 🎤 i hjørnet af hurtignoten eller en skriveside i notesbogen, og tal: ordene skrives, mens du taler, på appens sprog. Tryk igen for at stoppe. Første gang beder browseren om lov til at bruge mikrofonen. Virker i Chrome / Android og i Safari på iPhone. På en computer skal du bruge en mikrofon og en browser som Chrome, Edge eller Safari – mangler der noget, siger beskeden præcis hvad.",
    faq_q_dictation: "Kan jeg tale i stedet for at skrive?",
    faq_a_secret_room: "Et rum, der kun er dit, inde i New Me – et hus inden i et kæmpetræ. Du ser én væg ad gangen og drejer med pilene (eller ved at swipe). Den første nøgle kommer efter et ✓ ved et måltid på 3 forskellige dage og åbner døren – og hele rummet med den: computeren, spillet, pladespilleren, hylden med biblioteket indeni og katten. Derefter giver hver gennemført udfordring (også ugens udfordring) en nøgle, der åbner det næste sted: stjernetaget, verandaen ved havet, guitaren og dagbogen, åndedrætsrummet, skovstien med yoga, vandfaldet og en overraskelse på taget – og den 8. bringer en flaske fra havet med brevet fra fortiden indeni. Når noget åbner, viser en pil vejen. Den lille låge nederst på spilmaskinen åbner også – indtil videre er skabet bag den tomt. På stjernetaget falder en stjerne, du trykker på, som et stjerneskud, og katten sidder på puden.",
