    room_wall_window_hint: "Tryk på en ting for at komme tættere på · pilene drejer værelset",
    room_wall_window_title: "Vinduet og computeren",
    faq_a_steps_in_sport: "Øverst i Træningssporing, i en lille stribe: skridtene i dag og denne uge. Skridtene tælles automatisk, når appen bliver forbundet med Google Fit / Apple Health i telefonversionen – 🔗-knappen ved siden af forklarer det.",
    faq_q_steps_in_sport: "Hvor er den daglige skridttæller?",
    sport_steps_today_label: "skridt i dag",
    sport_steps_week_label: "denne uge",
    faq_a_reminders_one_place: "Hver påmindelse kommer én gang, ét sted. Hvis appen er åben foran dig (på computeren, iPad'en eller telefonen), vises den der; ellers kommer den som notifikation kun til telefonen. '✅ Færdig, tak!' eller 'Forstået!' hvor som helst lukker den på alle enheder, og den kommer ikke igen. 'Ikke endnu' udsætter den: den kommer igen hvert 5. minut, hver gang ét sted. At sætte ✓ ved opgaven på listen tæller også som færdig. For også at få notifikationerne på computer og tablet skal du slå 'Også på computer og tablet' til under Indstillinger > Notifikationer.",
    faq_q_reminders_one_place: "Hvorfor kommer en påmindelse kun én gang, og kun til telefonen?",
    reminder_all_devices_hint: "Som standard kommer hver påmindelse én gang, ét sted: til telefonen eller til den enhed, hvor appen er åben foran dig. Færdig eller Forstået ét sted lukker den overalt.",
    reminder_all_devices_label: "Også på computer og tablet",
    myday_water_info: "8 mellemstore / små glas vand er i gennemsnit cirka 2 liter",
    faq_a_good_things: "Om aftenen (fra kl. 18) dukker en lille knap op under datoen: skriv op til 3 gode ting, der skete i dag – én er nok. De gemmes, og under \"Tidligere dage\" ser du, hvad du skrev før. \"Ikke i aften\" skjuler den til i morgen, og du kan slå den helt fra under Indstillinger > Personalisering og kalender.",
    faq_a_home_countdown: "Markér en begivenhed med ⭐ i kalenderen (stjernen ved siden af den i listen over begivenheder). Den nærmeste markerede begivenhed inden for de næste 100 dage vises under datoen – \"3 dage tilbage · Mors fødselsdag\", \"I morgen · …\" eller \"I dag · …\". Tryk på den for at gå til den dag i kalenderen.",
    faq_a_home_streak: "Den tæller, hvor mange dage i træk du har haft mindst ét ✓ – hvad som helst i Min Dag, Min Rutine, Mine Mål eller New Me. Den vises fra 2 dage. Har du intet ✓ i dag endnu, er stimen ikke brudt – hele dagen er tilbage. Og hvis den slutter, forsvinder den bare stille, uden dårlig samvittighed.",
    faq_a_home_weather: "Slå \"Vejret på himlen på startskærmen\" til under Indstillinger > Personalisering og kalender, og tillad placering. Så viser himlen på startskærmen det rigtige vejr der, hvor du er – sol (eller måne og stjerner om natten), skyer, regn, sne, torden eller tåge – i alle temaer, opdateret cirka hvert 40. minut. Din omtrentlige placering (afrundet til cirka 1 km) bliver kun på din enhed og tjekkes via vores server hos MET Norway. Som standard er det slået fra. Under kontakten står der, hvordan vejret er udenfor lige nu – for eksempel ⛅ Let skyet, derfor viser himlen både sol og skyer.",
    faq_q_good_things: "Hvad er \"3 gode ting fra i dag\"?",
    faq_q_home_countdown: "Hvordan får jeg en nedtælling på startskærmen?",
    faq_q_home_streak: "Hvad er 🔥 \"dage i træk\" under hilsenen?",
    faq_q_home_weather: "Hvordan får jeg vejret på himlen på startskærmen?",
