    settings_good_things_label: "\"3 gode ting\" om aftenen",
    settings_weather_hint: "Regn, skyer eller sne i baggrunden på startskærmen, efter vejret der, hvor du er. Din omtrentlige placering bliver på denne enhed og tjekkes via vores server hos MET Norway.",
    settings_weather_label: "Vejret på himlen på startskærmen",
    weather_failed: "Vejret kunne ikke tjekkes lige nu.",
    weather_location_denied: "Ingen adgang til placeringen – tillad den i browserens indstillinger, og prøv igen.",
    faq_a_home_focus: "Tryk på ◎ øverst på startskærmen: alt forsvinder undtagen den ene ting for nu – det, der er i denne time, eller den næste ting på dagens liste – med et stort ✓, plus Hurtig Note. Efter ✓ dukker den næste ting op. Tryk på 'Fokustilstand ✕' øverst for at få det hele tilbage.",
    faq_a_home_search: "Åbn menuen ☰ – søgningen ligger helt øverst. Skriv mindst 2 bogstaver: resultaterne kommer fra dine noter, indkøbslisten, kalenderen, opskrifter, notesbøger (titler og sidetekst), mål, tabeller og bøger, grupperet efter type – tryk på et for at gå direkte derhen.",
    faq_a_my_day: "Min Dag samler det, der før var Et Kig på I Dag og Min Rutine, på én tidslinje. Nederst på startskærmen ser du, hvor meget der er gjort, hvad der er nu eller næste (med et hurtigt ✓) og ved siden af titlen et glas vand med +1. Tryk på den (eller stryg op) for at åbne hele dagen: øverst det, der ikke har et tidspunkt, derefter alt time for time – opgaver, begivenheder og møder fra kalenderen, faste ugentlige tider, dagens rutine, de små skridt i dine mål og New Me-måltider – med en linje for nu. Filtrér på Opgaver, Rutine eller Møder og begivenheder. Et ✓ her er det samme ✓ som alle andre steder (Min Rutine, Mine Mål, kalenderen) og får en marguerit i hjørnet til at springe ud. 'Rediger rutinen' åbner Min Rutine (findes også i menuen), og '＋ Tilføj for i dag' tilføjer en opgave for i dag. Et tryk på titlen \"Min Dag\" (eller på den lille streg øverst) lukker den igen.",
    faq_q_home_focus: "Hvad er fokustilstand?",
    faq_q_home_search: "Hvordan søger jeg i hele appen?",
