    gv_journey_day: "Dag {n} på rejsen",
    gv_today_all_done: "Alt er gjort 💜",
    gv_today_empty: "Ingen små skridt for i dag endnu – giv et hvilket som helst mål et lille skridt ✏️",
    gv_today_title: "Dagens små skridt",
    gv_note_text: "Vi behøver ikke være perfekte – bare gøre lidt hver dag for at komme videre.",
    gv_note_title: "På vej mod 10 · vi stopper ikke",
    gv_back: "Tilbage",
    faq_a_food_not_fried_default: "Nej. Medmindre det står (friturestegt, stegt i olie, schnitzel, paneret, pommes frites …), regnes maden som ovnbagt, grillet eller lavet på pande næsten uden olie. 'På panden' betyder højst lidt olie – ikke friture – og at nævne ovn eller pande ændrer ikke portionsstørrelsen. Noget friturestegt? Skriv det bare (for eksempel 'friturestegt kyllingebryst').",
    faq_q_food_not_fried_default: "Antager AI'en, at maden er friturestegt?",
    faq_a_routine_nudge: "Når noget ikke er blevet krydset af ✓ i mere end 3 dage (kun de dage, det skal gøres, tæller), spørger et venligt kort øverst, om det stadig er en del af rutinen, og om det virker – måske skal noget ændres for at komme videre:\n• ✓ Ja, fortsæt – ingen flere spørgsmål om det i en uge.\n• ✏️ Ændr – åbner det til redigering.\n• 🗑️ Fjern – tager det ud af rutinen.\n• ✕ – ikke nu.\nNår mere end 3 ting venter (måske var der ferie), spørger ét enkelt kort om dem alle på én gang: fortsæt som normalt, eller ændr noget – hvilket åbner listen over de ting, hver med ✏️ / 🗑️.\nKortet vises kun, når ✓-sporing er slået til og i brug. Den samme ting kopieret til flere dagfaner tæller som én.",
    faq_q_routine_nudge: "Hvorfor spørger Min Rutine om et punkt?",
    faq_a_routine_day_tabs: "Ja. Vælg 'Dage for denne fane' i ⚙️ – på de dage åbner Min Rutine direkte på den, og en lille prik markerer den. En fane, der hedder som en dag (f.eks. 'søndag'), genkendes automatisk, og dagskabelonerne sætter dagene selv. Når en fane har dage, tæller ✓-spørgsmålet kun de dage, hvor dens punkter findes.",
    faq_q_routine_day_tabs: "Kan Min Rutine åbne på dagens fane?",
    faq_a_routine_add_templates: "Tryk på ➕ i Min Rutine, og vælg:\n• ✏️ Ny tom fane.\n• 📄 Duplikér den aktuelle fane – alle tider og punkter kopieres (uden ✓-historikken). Når en dagsfane som 'søndag' duplikeres, foreslås næste ledige dag automatisk – den hurtigste måde at lave en anden rutine for hver dag på.\n• ⭐ Færdige skabeloner (Premium): én fane for hver dag (søndag–torsdag, mandag–fredag, søndag–fredag eller hele ugen) – tomme, eller hver dag som en kopi af den aktuelle fane – og 10 færdige rutiner med indhold: rolig morgen, aften & god søvn, arbejdsdag, hjemmearbejde, studiedag, træningsdag, faste måltider, rolig dag, dag med børnene og weekend. Alt kan redigeres bagefter.",
    faq_q_routine_add_templates: "Hvordan duplikerer jeg en fane eller bruger en færdig skabelon i Min Rutine?",
    routine_tpl_weekend_items: "09:00 Sove længe + rolig morgenmad\n11:00 Familie eller venner\n13:00 Frokost\n15:00 Hvile\n17:00 Gåtur\n19:00 Aftensmad\n21:00 Film eller rolig aften",
    routine_tpl_weekend: "Weekend",
    routine_tpl_kids_items: "07:00 Stå op + morgenmad sammen\n08:00 Aflevere i institution og skole\n14:00 Hente + frokost\n16:00 Leg eller tid udenfor\n18:00 Aftensmad\n19:00 Bad + nattøj\n20:00 Godnathistorie og sove\n21:00 Tid til mig selv",
    routine_tpl_kids: "Dag med børnene",
    routine_tpl_calm_items: "08:00 Kaffe eller te uden mobilen\n10:00 Gåtur udenfor\n12:00 Nærende måltid\n15:00 Noget sjovt – en hobby\n17:00 Ring til en, man holder af\n20:00 Bad eller rolig stund\n22:00 3 gode ting fra i dag",
    routine_tpl_calm: "Rolig dag",
    routine_tpl_eating_items: "08:00 Morgenmad\n10:00 Vand + frugt\n13:00 Frokost\n16:00 Mellemmåltid\n19:00 Aftensmad\n21:00 Køkkenet lukket (vand eller te er fint)",
    routine_tpl_eating: "Faste måltider",
    routine_tpl_workout_items: "07:00 Vand + let mellemmåltid\n08:00 Træning\n09:00 Morgenmad med protein\n13:00 Afbalanceret frokost\n16:00 Mellemmåltid\n19:00 Aftensmad\n21:00 Udstrækning\n22:00 Sove 7–8 timer",
    routine_tpl_workout: "Træningsdag",
    routine_tpl_study_items: "08:00 Morgenmad\n09:00 Studere (50 minutter + 10 pause)\n11:00 Anden studierunde\n13:00 Frokost + hvile\n14:00 Øve opgaver\n16:00 Gåtur eller sport\n19:00 Repetere dagens stof\n22:00 Sove til tiden",
    routine_tpl_study: "Studiedag",
    routine_tpl_home_office_items: "07:00 Stå op + tage tøj på (ikke pyjamas)\n08:00 Morgenmad + kaffe\n09:00 Fokustid\n11:00 Udstrækning + vand\n13:00 Frokost\n14:00 Møder og opkald\n16:00 Kort gåtur udenfor\n17:00 Luk computeren",
    routine_tpl_home_office: "Hjemmearbejde",
    routine_tpl_workday_items: "07:00 Stå op + vand\n08:00 Morgenmad\n09:00 Fokuseret arbejde – den vigtigste opgave\n11:00 Kort pause + vand\n13:00 Frokost væk fra skærmen\n15:00 Mails og opkald\n17:00 Afslut dagen + planlæg i morgen\n19:00 Fritid",
    routine_tpl_workday: "Arbejdsdag",
    routine_tpl_evening_items: "19:00 Let aftensmad\n20:00 Rydde op 10 minutter + gøre klar til i morgen\n21:00 Skærmene slukket + bad\n22:00 Læse i sengen og sove",
    routine_tpl_evening: "Aften & god søvn",
    routine_tpl_morning_items: "06:00 Stå op + et glas vand\n07:00 10 minutters udstrækning\n08:00 Sund morgenmad\n09:00 Planlæg dagens 3 vigtigste ting",
    routine_tpl_morning: "Rolig morgen",
