    nm_letter_gift_title: "Brevet fra fortiden",
    nm_gift_locked_view: "Gaven åbnes efter alle {n} udfordringer – {left} tilbage.",
    nm_gift_intro: "Alle {n} udfordringer, skridt for skridt. Her er, hvad der ventede:",
    nm_gift_title: "Din gave",
    faq_a_new_me_letter_gift: "I starten af New Me (eller senere under Udfordringer) kan der skrives et brev til dig selv i fremtiden. Når det er forseglet, kan det ikke læses eller redigeres, før det åbnes: i flasken fra havet i det hemmelige værelse eller efter alle 20 udfordringer – hvor der også venter en gave.",
    faq_q_new_me_letter_gift: "Hvad er brevet fra fortiden?",
    faq_a_new_me_challenges: "🏆 Udfordringer har 20 udfordringer: 10 store (som 5 dage uden sukker, en uge uden kulhydrater eller tabe 4 kg på en måned – kalorieunderskud, træning og intet sukker hver dag) og 10 mini – små vaner i en uge, som kanelkaffe uden sukker. Når en udfordring vælges, kommer spørgsmålet om, hvornår den skal starte: i dag, i morgen, næste uge eller en anden dato. En stor og en miniudfordring kan køre samtidig. En igangværende udfordring vises øverst i menuen og i Min Dag, med et ✓ for dagen. Hver uge af en udfordring giver én fridag (🍕), der ikke bryder den, og en dag uden flueben tæller som fridag – i dag og i går kan markeres. Nogle dage markeres automatisk: en træning på 20 minutter i Træningssporing eller menuens måltider med ✓. Hver udfordring har et ⓘ med, hvad der præcis tæller (for eksempel hele listen over kulhydrater) – i selve udfordringen og ved siden af i Min Dag. Under dem har 🌱 Personlig udvikling 48 små udfordringer for en uge (de tæller ikke med i de 20) – se »Hvad er ugens udfordring?«.",
    faq_q_new_me_challenges: "Hvordan fungerer udfordringerne i New Me?",
    nm_letter_too_short: "Et par ord mere 🙂",
    nm_letter_quiz_note: "Valgfrit – det kan også skrives senere, under Udfordringer.",
    nm_letter_write: "✍️ Skriv brevet",
