    faq_a_workout_calories: "Ja. Hver træning får et skøn over de forbrændte kalorier – ud fra type, varighed og din seneste vægt (ved løb og cykling også ud fra fart, når en distance er indtastet). Det vises i træningslisten og i månedsoversigten (Forbrændt) og lægges til dagens kaloriebudget: i Daglig Måltidssporing, i Kalorie- og vægtoversigt og i New Me-ringen. Det er et skøn, derfor vises det med ~.",
    faq_q_workout_calories: "Tæller træning med i dagens kalorier?",
    faq_a_new_me_flexible_menu: "Ja. I spørgeskemaet og i indstillingerne vælger du, hvor mange måltider om dagen – 2 måltider + et mellemmåltid / 2 måltider + en let aftensmad / 2 måltider + et mellemmåltid + en let aftensmad – og ➖ på et måltidskort fjerner det (mindst 3 bliver); »➕ Læg tilbage« henter det igen. Under alle omstændigheder bliver dagens kalorier de samme: det, der fjernes, fordeles på de andre måltider, og under hvert måltid står, hvor meget der kom til, og hvad der passer til. ✏️ Rediger på et måltid åbner teksten – ret det, du vil (f.eks. uden brød eller med et æg mere), så regner AI kalorier og protein ud igen. 🔄 Byt giver muligheder fra menuen, ⭐ Gemte og ✨ Skriv selv; hver ændring kan gælde kun i dag eller fra nu af. Og nederst i »Hele dagen« er der ➕ Tilføj mad – skriv, hvad der blev spist uden for menuen, så regner AI det ud og lægger det til i dag (✕ sletter).",
    faq_q_new_me_flexible_menu: "Kan jeg ændre antallet af måltider i New Me, eller spise et eget måltid?",
