    sport_total_kcal: "Forbrændt",
    nm_swap_ai_too_big: "Lidt mere end det, der er tilbage i dag – op til ~{n} kcal kan være der. Du kan stadig notere det – resten af dagens måltider bliver mindre for at udligne – eller vælge en mindre portion.",
