    vision_tagline: "Store mål, små skridt.",
    faq_a_app_tour: "Rundvisningen åbner automatisk én gang, første gang du kommer ind. Den begynder med sine dele – tryk på en for at springe direkte dertil – og viser derefter alle dele af appen (startskærmen, AI-assistenten og hvert menupunkt) og de fem grupper i Indstillinger, hver med en kort forklaring, og kigger ind i nogle af dem (for eksempel en eksempelsti for et mål, tasken og Google Calendar). Fortsæt går videre, Tilbage går tilbage, Spring denne del over springer til næste del, og ✕ lukker rundvisningen. Du kan se den igen når som helst under Indstillinger > Hjælp og brug > App-rundvisning og fortsætte, hvor du slap. Fortsæt og Tilbage er altid samme sted nederst på skærmen, og på en computer virker piletasterne også.",
    faq_q_app_tour: "Hvordan ser jeg app-rundvisningen igen?",
