    table_select_option_delete_title: "Slet mulighed",
    faq_a_other_manual_option: "Overalt hvor du vælger fra en liste med muligheder, findes også '✏️ Andet' - vælg den og skriv præcis det, du har brug for. I en tabel med en valgkolonne (for eksempel 'Relation' i en gavetabel) trykker du på cellen, vælger '✏️ Andet', skriver værdien (for eksempel 'Nevø') og trykker på Tilføj - den gemmes som en ny mulighed i kolonnen, så næste gang er den allerede på listen. Det lille × ved siden af hver mulighed på listen sletter muligheden fra kolonnen. Når du vælger et tabelikon, er der mange ikoner (bl.a. farverige huskesedler). Det fungerer på samme måde for kategorier for gemte måltider, opskriftskategorier, kategorier for faste udgifter (gemmes som en ny personlig kategori) og målkategorier i Mine Mål.",
