    faq_a_receipts_total: "På skærmen Fakturaer / Kvitteringer trykker du på 🧮 'Sum af alle kvitteringer'. Vælg fra hvilket år til hvilket år (som standard fra den ældste kvittering til i år), tryk på Beregn, så vises summen af begge kategorier samlet - Husholdningsudgifter og Erhvervsudgifter - samt antallet af kvitteringer og summen for hver kategori for sig.",
    faq_q_receipts_total: "Hvordan lægger jeg alle kvitteringer for en periode sammen?",
    receipts_total_empty: "Ingen kvitteringer i disse år.",
    receipts_total_invalid: "Indtast et gyldigt årsinterval",
    receipts_total_count: "Kvitteringer: {count}",
    receipts_total_calc_btn: "Beregn",
    receipts_total_to_year: "Til år",
    receipts_total_from_year: "Fra år",
    receipts_total_title: "Sum af alle kvitteringer",
    receipts_total_tile: "Sum af alle kvitteringer",
    faq_a_quick_note_apple: "🍎 ved siden af 📝 og 🛒 i notevinduet er en genvej til hurtigt at registrere et af dine gemte måltider i dagens Daglig Måltidssporing. Den er slået til som standard - hvis du ikke har brug for den, kan du slå den fra under Indstillinger > Personalisering og kalender ('Vis 🍎-genvejen til gemte måltider i notevinduet') og slå den til igen der når som helst.",
    faq_q_quick_note_apple: "Hvad er 🍎 i notevinduet, og kan jeg skjule den?",
    settings_quick_note_apple_label: "Vis 🍎-genvejen til gemte måltider i notevinduet",
    faq_a_vision_board_today: "I Mine Mål trykker du under et måls sti (i 'Planen') på 📅 ved siden af en milepæl og vælger en dato. Du kan også slå '🔁 Hver uge, indtil det er gjort' til – så kommer milepælen igen hver uge på samme dag, indtil du sætter kryds ved den én gang. Milepælen vises på den valgte dag i Min Dag og i kalenderen (og i Google Calendar, hvis den er forbundet), og knappen viser, hvornår den er planlagt. Et ✓ ét sted sætter også kryds det andet sted og fører målets sti frem. Tryk på 📅 igen for at ændre datoen eller fjerne milepælen fra kalenderen. Sletter du en engangsopgave fra kalenderen, slettes milepælen også fra målet; sletter du én uge af en ugentlig påmindelse, fjernes kun den uge.",
    faq_q_vision_board_today: "Hvordan sætter jeg en milepæl fra et mål i kalenderen (📅)?",
    vision_milestone_already_today: "Dette trin er allerede i dagens opgaver.",
    auth_consent_required: "Oprettelse kræver accept af Brugsvilkårene og Privatlivspolitikken.",
    auth_consent_privacy: "Privatlivspolitikken",
    auth_consent_terms: "Brugsvilkårene",
    auth_consent_label: "Jeg har læst og accepterer {terms} og {privacy}, og jeg er 16 år eller ældre.",
    nm_bonus_sub: "En kort tekst om vejning, at gå over målet og at spise ude",
    nm_bonus_label: "Bonus",
    nm_shortcut_title: "New Me – min menu i dag",
    nm_remove: "Fjern",
    nm_split_line: "Plan {plan} · Drikke {drinks} · Ekstra {extra}",
    nm_extras_hint: "Fra Daglig Måltidssporing og hurtig tilføjelse – allerede talt med i ringen.",
    nm_extras_title: "Også spist i dag",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Indtast drikkens navn og kalorier",
    nm_drink_more: "+ En drik mere",
    nm_drink_add: "Tilføj",
    nm_drink_name_ph: "Drik (f.eks. juice)",
    nm_drinks_hint: "Skriv bare drikken – kalorierne beregnes automatisk, og tallet kan ændres.",
    nm_slot_drinks: "Drikke",
    faq_a_new_me_tracking: "Tryk på den næste mission øverst i New Me og derefter på ✓ Spist for at markere det næste måltid som spist – hele menuen med ✓ på hvert måltid findes under Hele dagen, på siden, og dagens måltider vises også i Min Dag på startskærmen – et tryk på et af dem dér (eller musen over det) viser præcis, hvad der skal spises, med ✓ og Byt. Alt synkroniseres med Daglig Måltidssporing: planens måltider, drikke og alt, hvad du tilføjer andre steder (f.eks. en kaffe fra hurtig tilføjelse), tælles sammen i New Me og i Min Dag – intet, du allerede har skrevet, overskrives, og at fjerne et ✓ fjerner kun New Me-delen. Når alle dagens måltider er krydset af, er der en lille fejring. Under »Drikke« noterer du dagens drikke – samlet op til ~150 kcal, altså cirka 3 drikke på op til ~50 kcal hver. Skriv bare navnet på drikken, så udfyldes kalorierne automatisk med AI. De to rækker med kaffe/te har også feltet »Mælk? Hvor meget?« (f.eks. »lidt« eller »50 ml«), og beregningen opdateres; tallet kan ændres både før og efter, at drikken er tilføjet. En drik med navn og kalorier gemmes automatisk, så snart du går videre – at trykke på Tilføj er valgfrit. Tryk på ☆ ved siden af en drik for at gemme den som fast drik – faste drikke vises som knapper øverst på Drikke-kortet, og ét tryk tilføjer dem til dagen. ⭐ gemmer et måltid som gemt måltid. »Dagstabel« viser, hvad du har spist, med kalorier og protein. Den lille 💎 ved siden af fokustilstand, øverst på startskærmen, åbner det direkte. Kalorie- og proteinværdier er AI-estimater og kan indeholde fejl. Spiste du ikke det hele? Under et afkrydset måltid trækker »Spiste ikke det hele?« en fjerdedel, halvdelen eller tre fjerdedele af portionen fra – eller det, du skriver, udregnet – og dagens kalorier opdateres.",
    faq_q_new_me_tracking: "Hvordan fungerer ✓, bytter og kalorier i New Me?",
    faq_a_new_me_what: "New Me er et separat dagsmenuprogram med to færdige planer – 1.300 eller 1.500 kalorier – bygget af 2 hovedmåltider og 2 mellemmåltider, med 3 muligheder til hvert. Hele Premium er inkluderet. Pris: $11.99 om måneden (opsig når som helst) eller $99.99 én gang, livstid. Det åbnes via 💎 New Me i menuen. Før start er der et kort spørgeskema, der begynder med en medicinsk ansvarsfraskrivelse, som skal accepteres. Programmet er kun generel information og erstatter ikke en læge eller klinisk diætist.",
    faq_q_new_me_what: "Hvad er New Me, og hvordan får jeg det?",
