    nm_unlock_pending: "Betaling modtaget – det kan tage et minut, før den vises. Opdater siden om lidt.",
    nm_unlocked_toast: "New Me er låst op – velkommen! 💎",
    nm_unlocking: "Bekræfter dit køb…",
    nm_buy_btn: "Få New Me",
    nm_sales_f4: "Hele menuen som PDF på dit sprog",
    nm_sales_f3: "En månedsvisning med vægtopfølgning",
    nm_sales_f2: "Et dagligt ✓ for hvert måltid, plus hvor mange kalorier du har tilbage i dag",
    nm_sales_f1: "To færdige planer (1.300 / 1.500 kcal) med 3 muligheder til hvert måltid",
    nm_sales_subtitle: "En færdig dagsmenu på 1.300 eller 1.500 kalorier – med opfølgning, smarte bytter, udfordringer og en rejse mod fremskridt.",
    faq_a_categories_menu: "Appens menu kan vises på én af to måder, og der vises kun én knap øverst: ☰ en liste (standard) eller ▦ store felter - Planlægning og Kalender, Lister, Mål og Fremskridt, Ernæring og Målinger, Sport, og Udgifter og Indtægter; tryk på et felt for at se, hvad det indeholder, og tryk derefter på det, du har brug for. For at skifte åbner du menuen og trykker på den lille knap øverst i den: ▦ i listemenuen skifter til felter, og ☰ i feltmenuen skifter tilbage til listen. Feltmenuen har også en ⚙️-knap til Indstillinger. Dit valg gemmes og gælder på alle dine enheder.",
    faq_q_categories_menu: "Hvordan skifter jeg mellem ☰-listemenuen og ▦-feltmenuen?",
