    settings_accessibility_statement_link: "♿ Tilgængelighedserklæring",
    recurring_task_tooltip: "Ugentlig tilbagevendende opgave",
    quick_add_ai_limit_toast: "Månedens AI-kvote er brugt op, så et hurtigere (mindre præcist) estimat blev brugt i stedet. Den nulstilles næste måned.",
    food_estimate_local_db_reasoning: "Fundet i vores fødevaredatabase, ikke gættet af AI. Tryk på \"Det er ikke korrekt\", hvis det ikke er den fødevare, du mente.",
    food_clarify_milk_question: "Er {ingredient} en mælkeerstatning blandet i drikken, eller en separat portion fast føde? Angiv også mængden.",
    food_ai_fallback_toast: "Det fulde AI-estimat kunne ikke nås lige nu, så dette er et hurtigt, groft estimat i stedet. Du kan redigere kalorierne manuelt eller prøve at registrere igen om et øjeblik.",
    daily_focus_badge_title: "Påmindelse: det vigtige i dag",
    calendar_event_star_title: "Markér som vigtig",
    auth_password_placeholder_login: "Adgangskode",
    routine_overview_no_checks: "Ingen afkrydsninger denne måned endnu - tryk på ✓ ved siden af dine rutinepunkter de dage, du gør dem.",
    faq_a_finance_cycle_day: "Som standard nulstilles din budgetoversigt den 1. i hver kalendermåned. Får du løn på en anden dag (f.eks. den 10.), så indstil den dag her i stedet - din månedsoversigt, historik og dit målbudget løber så fra den dag til samme dag næste måned i stedet for fra den 1. til slutningen af måneden.",
    faq_q_finance_cycle_day: "Hvad gør indstillingen 'Nulstillingsdag for månedsbudget'?",
    faq_a_quick_note_view_full_lists: "I menuen ☰ ligger Noter og Indkøbsliste lige der. I vinduet Hurtig Note (i Fokustilstand) fører de små 📝 og 🛒 ved siden af Tilføj dig også derhen, og 🍎 tilføjer hurtigt et af dine gemte måltider.",
    faq_q_quick_note_view_full_lists: "Hvordan ser jeg alle mine Noter eller hele Indkøbslisten fra Hurtig Note?",
    note_triage_otherdate: "Anden Dato", note_triage_otherdate_modal_title: "Vælg en dato", note_triage_otherdate_missing: "Vælg venligst en dato", note_triage_success_otherdate: "Tilføjet til din tidsplan!", notes_ai_placeholder_shopping: "Tilføj til listen",
    daily_greeting_morning: "God morgen!", daily_greeting_afternoon: "God eftermiddag!", daily_greeting_evening: "God aften!", daily_greeting_night: "Godnat!", calorie_monthly_view_title: "Månedsvisning", calorie_monthly_avg_label: "Daglige gennemsnit:", calorie_monthly_avg_empty: "Ingen data registreret endnu denne måned", calorie_monthly_day_total_label: "Dagens total:", notes_ai_added_shopping: "Tilføjet til din indkøbsliste", quick_note_dest_notes: "📝 Noter", quick_note_dest_shopping: "🛒 Indkøbsliste",
    faq_q_calorie_monthly_view: "Hvordan ser jeg min kaloriehistorik for en hel måned?", faq_a_calorie_monthly_view: "Kaloriemål har et 'Månedsvisning'-kort med en kalender - hver dag du har registreret mad får en prik, og månedens daglige gennemsnit vises over gitteret. Tryk på en dag for at se præcis hvad du spiste og totalen. Den samme opgørelse er også med, når du downloader din personlige rapport (PDF) fra Indstillinger, hvis afsnittet Kaloriemål er markeret.",
    faq_q_calorie_stats_total_vs_average: "Er de ugentlige/månedlige tal i Kalorie- og vægtoversigt en sum eller et gennemsnit?", faq_a_calorie_stats_total_vs_average: "Begge dele - det store tal er summen (totalen) af alt registreret i den aktuelle kalenderuge/måned, og den lille linje under er det daglige gennemsnit. Gennemsnittet divideres kun med de dage, du faktisk har registreret noget, ikke med 7 eller hele måneden - en dag uden nogen registrering springes simpelthen over, den tæller ikke som 0 og trækker ikke gennemsnittet ned.",
    faq_q_weight_note: "Kan jeg tilføje en note til en vægtregistrering?", faq_a_weight_note: "Ja - der er et valgfrit notefelt ved siden af vægt-/datofelterne i Periodisk Vægtsporing (du finder den nederst i Ernæring og Målinger > Kalorie- og vægtoversigt, under ⚖️). Brug det til kontekst som \"efter træning\" eller \"morgenvejning\" - den vises ved siden af den registrering på historiklisten.",
    faq_q_quick_note_shopping_list: "Kan Hurtig Note tilføje direkte til min indkøbsliste?", faq_a_quick_note_shopping_list: "Ja – på skrivelinjen midt på startskærmen trykker du på 📝 i starten: den bliver til 🛒, og det, du skriver, ryger direkte på Indkøbslisten uden om Noter.",
