    calorie_stat_avg_label: "Gns.: {amount}",
    daily_focus_modal_title: "🧠 Hvad er det vigtigste, du skal gøre i dag?", daily_focus_modal_subtitle: "Svar, så bliver det tilføjet direkte til dagens plan.", daily_focus_input_placeholder: "I dag vil jeg allermest", daily_focus_save_btn: "Tilføj til dagens plan", daily_focus_skip_btn: "Ikke nu", daily_focus_missing_text: "Skriv noget først", daily_focus_added_toast: "Tilføjet til dagens plan", daily_focus_other_option: "✍️ Andet...",
    daily_focus_c1_d0: "Beskytte mit rolige rum mod støjen omkring mig", daily_focus_c1_d1: "Sætte klare grænser, med kærlighed og uden skyldfølelse", daily_focus_c1_d2: "Blive stående forankret, selv når der er storm omkring mig", daily_focus_c1_d3: "Gøre min ro og min energi til topprioritet", daily_focus_c1_d4: "Ikke tage andres følelser og humør på mig", daily_focus_c1_d5: "Ikke lade andres ord ryste min selvværd",
    daily_focus_c2_d0: "Lytte til hvad min krop og mit sind har brug for", daily_focus_c2_d1: "Nyde de små ting undervejs", daily_focus_c2_d2: "Sænke tempoet og virkelig mærke efter i mig selv", daily_focus_c2_d3: "Give mig selv plads til at trække vejret midt i det hele", daily_focus_c2_d4: "Føle mig hjemme og i fred med mig selv", daily_focus_c2_d5: "Fokusere på det, der sker nu, uden at skynde mig fremad",
    daily_focus_c3_d0: "Lade mine ord være opmuntrende, tålmodige og forstående", daily_focus_c3_d1: "Ikke tage noget personligt", daily_focus_c3_d2: "Ikke antage noget - bare spørge, eller give slip", daily_focus_c3_d3: "Stole på mit eget tempo og min egen vej", daily_focus_c3_d4: "Give slip på perfektionen og vælge fremskridt", daily_focus_c3_d5: "Være tålmodig med min egen proces",
    daily_focus_c4_d0: "Afslutte dagen med en følelse af stolthed og tilfredshed", daily_focus_c4_d1: "Lægge mærke til mine fremskridt, selv i små skridt", daily_focus_c4_d2: "Fokusere på én opgave ad gangen", daily_focus_c4_d3: "Skabe orden i mine opgaver og handle roligt", daily_focus_c4_d4: "Acceptere mig selv præcis som jeg er i dag", daily_focus_c4_d5: "Vide hvornår jeg skal handle, og hvornår jeg skal give slip",
    daily_focus_c5_d0: "Bringe et smil og lethed ind i alt, hvad jeg gør", daily_focus_c5_d1: "Starte dagen med frisk, god energi", daily_focus_c5_d2: "Unde mig selv én rolig dag, fri for tunge forventninger", daily_focus_c5_d3: "Bringe enkel glæde ind i min hverdag", daily_focus_c5_d4: "Åbne mit hjerte for gode overraskelser i dag", daily_focus_c5_d5: "Starte dagen med taknemmelighed og et smil",
    daily_focus_c6_d0: "Lytte for alvor, ikke bare vente på min tur til at tale", daily_focus_c6_d1: "Huske at alle bærer på noget, man ikke kan se", daily_focus_c6_d2: "Sprede varm, imødekommende energi omkring mig", daily_focus_c6_d3: "Bevare åbenhed og respekt i den måde, jeg kommunikerer på", daily_focus_c6_d4: "Se det gode i menneskene omkring mig", daily_focus_c6_d5: "Give et venligt ord til nogen, der har brug for det i dag",
    daily_focus_c7_d0: "Huske hvad jeg har, ikke kun hvad der mangler", daily_focus_c7_d1: "Give slip på det, der ligger uden for min kontrol", daily_focus_c7_d2: "Værdsætte lærdommen, selv når tingene ikke går som planlagt", daily_focus_c7_d3: "Stoppe op et øjeblik og sige tak for det, jeg har", daily_focus_c7_d4: "Stole på mig selv og min evne til at klare tingene", daily_focus_c7_d5: "Bringe mig selv tilbage til en sund fornemmelse af proportioner",
    daily_focus_p1_d1_s1: "Beskytte mit rolige rum midt i presset omkring mig", daily_focus_p1_d1_s2: "Lytte til, hvad krop og sind har brug for i dag", daily_focus_p1_d1_s3: "Holde mine ord opmuntrende, tålmodige og forstående", daily_focus_p1_d1_s4: "Tage små skridt, der skaber ren fremgang", daily_focus_p1_d1_s5: "Bringe et smil og lethed ind i alt, hvad jeg gør",
    daily_focus_p1_d2_s1: "Sætte klare grænser ud fra kærlighed og tryghed", daily_focus_p1_d2_s2: "Give slip med kærlighed på det, der ligger uden for min kontrol", daily_focus_p1_d2_s3: "Vælge en positiv og konstruktiv fortolkning af enhver situation", daily_focus_p1_d2_s4: "Se og værdsætte mine fremskridt hen over dagen", daily_focus_p1_d2_s5: "Starte dagen med god, fornyet energi",
