    faq_q_daily_focus_prompt: "Hvad er den lille påmindelse, der spørger, hvad der er vigtigst for mig at gøre i dag?", faq_a_daily_focus_prompt: "Det er en daglig Premium-påmindelse: én gang om dagen dukker der et lille »1«-mærke op på AI-assistentens ikon. Tryk på mærket for at åbne en boble, der spørger, hvad der er vigtigst for dig at gøre i dag, med 5 færdige forslag med det samme (de skifter dagligt og roterer gennem et helt år med forskellige temaer, så de holder sig friske) plus 'Andet' til at skrive dit eget - du kan vælge mere end ét. Tryk på Tilføj, så vises dine valg som små påmindelsesmærker øverst i 'Min Dag' (de er ikke opgaver, der skal krydses af). Lukker du den med ✕ eller trykker udenfor, falmer mærket bare resten af dagen i stedet for at forsvinde. Den er slået til som standard, men du kan slå den fra under Indstillinger > Personalisering og kalender. Ikke den rette dag? Tryk på '🌙 Ikke i dag' – mærket forsvinder til i morgen, og så kommer spørgsmålet tilbage som normalt. Et af forslagene kommer fra dit eget liv – næste skridt i månedens mål eller dagens læsning. Hver dag begynder forfra.",
